// Extract body from Webhook payload
const body = $input.item.json.body || $input.item.json;

// Generate Visit ID: TAMU-YYYYMMDD-XXXX
const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
const day = String(now.getDate()).padStart(2, '0');
const random4 = Math.floor(1000 + Math.random() * 9000);
const idKunjungan = body.idKunjungan || `TAMU-${year}${month}${day}-${random4}`;

const jamKunjungan = body.jamKunjungan || now.toISOString();

const processedData = {
  idKunjungan,
  nama: body.nama || '',
  instansi: body.instansi || '',
  telepon: body.telepon || '-',
  jamKunjungan,
  jamKeluar: '',
  keterangan: body.keterangan || '',
  tandaTangan: body.tandaTangan || '',
  tandaTanganKeluar: '',
  status: 'SEDANG BERKUNJUNG',
  durasi: '-',
  createdAt: now.toISOString(),
  lastUpdated: now.toISOString()
};

return { json: processedData };

const body = $input.item.json.body || $input.item.json;
const jamKeluar = body.jamKeluar || new Date().toISOString();
const jamMasuk = body.jamKunjungan ? new Date(body.jamKunjungan) : new Date(Date.now() - 3600000);

const start = new Date(jamMasuk);
const end = new Date(jamKeluar);
let diffMs = end - start;
if (diffMs < 0) diffMs = 0;

const totalMinutes = Math.floor(diffMs / (1000 * 60));
const hours = Math.floor(totalMinutes / 60);
const minutes = totalMinutes % 60;
let durasi = `${minutes} Menit`;
if (hours > 0) {
  durasi = `${hours} Jam ${minutes} Menit`;
}

return {
  json: {
    idKunjungan: body.idKunjungan,
    jamKeluar,
    tandaTanganKeluar: body.tandaTanganKeluar || '',
    status: 'SELESAI',
    durasi,
    lastUpdated: new Date().toISOString()
  }
};
